import { expect, test } from "@e2e/fixtures";
import * as flows from "@e2e/flows";
import * as ui from "@e2e/ui-actions";

test.describe("Download popover", () => {
  test("Download button is visible and enabled after session start", async ({ inspectorPage }) => {
    await test.step("Assert download button is visible and enabled", async () => {
      await ui.downloads.assertions(inspectorPage).buttonIsVisible();
      await ui.downloads.assertions(inspectorPage).buttonIsEnabled();
    });
  });

  test("Download popover offers E2E and Tracker logs exports", async ({ inspectorPage }) => {
    await flows.downloads.openDownloadPopoverAndAssert(inspectorPage);
    const e2eDownload = await flows.downloads.downloadE2eFile(inspectorPage);

    await test.step("Assert downloaded E2E file is a YAML file", () => {
      const filename = e2eDownload.suggestedFilename();
      expect(filename).toMatch(/^e2e-test-.*\.yml$/);
    });

    await flows.downloads.openDownloadPopoverAndAssert(inspectorPage);
    const trackerLogsDownload = await flows.downloads.downloadTrackerLogsFile(inspectorPage);

    await test.step("Assert downloaded tracker logs file is a JSON file", () => {
      const filename = trackerLogsDownload.suggestedFilename();
      expect(filename).toMatch(/^tracker-logs-.*\.json$/);
    });
  });

  test("Downloaded tracker logs JSON contains messages from multi-turn chat", async ({
    inspectorPage,
  }) => {
    await flows.chat.sendMessageAndAssert(inspectorPage, "Hi there!");
    await flows.chat.sendMessageAndAssert(inspectorPage, "What's my balance?");
    await flows.downloads.downloadTrackerLogsAndAssertContent(inspectorPage, [
      "Hi there",
      "balance",
    ]);
  });

  test("Downloaded E2E YAML contains flow steps recorded during session", async ({
    inspectorPage,
  }) => {
    await flows.chat.sendMessageAndAssertBotReplies(inspectorPage, "What's my balance?", {
      expectedBotMessageCount: 3,
    });
    await flows.downloads.downloadE2eYamlAndAssertContent(inspectorPage, ["check_balance"]);
  });
});
